// Normalizar chat: toma solo el texto escrito por el empleado. El canal lo fija el workflow.
const j = $input.first().json || {};
return [{ json: { origen: 'CHAT', texto: typeof j.chatInput === 'string' ? j.chatInput : '', legajo_declarado: '', campos_ignorados: [] } }];

// Validación previa: lógica fija, sin IA. Decide si la consulta puede pasar a WF-03.
// Genera el identificador de la consulta a partir de la ejecución de WF-02; el usuario no puede elegirlo.
const n = $input.first().json;
const texto = String(n.texto || '').replace(/\s+/g, ' ').trim();
const id_consulta = 'CON-' + $execution.id;
const fecha_hora = $now.setZone('America/Argentina/Buenos_Aires').toFormat('yyyy-MM-dd HH:mm');
const MAX = 1000;

const RESP_FORMATO = 'Para atender tu consulta necesito tu legajo al inicio del mensaje, con el formato LEG-0000. Por ejemplo: LEG-0007 ¿Cuántos días de vacaciones tengo disponibles?';
const RESP_VACIO = 'No recibí ninguna consulta. Escribí tu legajo y tu consulta completa en un solo mensaje, por ejemplo: LEG-0007 ¿Cuántos días de vacaciones tengo disponibles?';
const RESP_LARGO = 'Tu mensaje es demasiado largo. Resumí la consulta en menos de ' + MAX + ' caracteres y volvé a enviarla con tu legajo al inicio.';
const RESP_SALUD = 'Por tu privacidad, no proceso información de salud por este canal. No incluyas diagnósticos, síntomas ni tratamientos. Para temas de licencias médicas comunicate con Salud Ocupacional.';

const base = { id_consulta, origen: n.origen, fecha_hora, campos_ignorados: n.campos_ignorados || [] };
const fin = (resultado, motivo, respuesta, extra = {}) => [{ json: { ...base, resultado, motivo, respuesta, ...extra } }];

if (!texto) return fin('RECHAZADA', 'MENSAJE_VACIO', RESP_VACIO);
if (texto.length > MAX) return fin('RECHAZADA', 'MENSAJE_DEMASIADO_LARGO', RESP_LARGO);

// Legajo: al inicio del mensaje; en el webhook también puede venir en el campo "legajo".
const m = texto.match(/^LEG-(\d{4})\b/i);
const enMensaje = m ? 'LEG-' + m[1] : '';
const declarado = String(n.legajo_declarado || '').trim().toUpperCase();
if (declarado && !/^LEG-\d{4}$/.test(declarado)) return fin('RECHAZADA', 'LEGAJO_FORMATO_INVALIDO', RESP_FORMATO);
if (declarado && enMensaje && declarado !== enMensaje) return fin('RECHAZADA', 'LEGAJO_INCONSISTENTE', RESP_FORMATO);
const legajo = declarado || enMensaje;
if (!legajo) return fin('RECHAZADA', 'SIN_LEGAJO', RESP_FORMATO);
const consulta = texto.replace(/^LEG-\d{4}[\s:,.-]*/i, '').trim();
if (!consulta) return fin('RECHAZADA', 'MENSAJE_VACIO', RESP_VACIO, { legajo });

// Posible información clínica: no llega al modelo ni a WF-03. Detección por patrones (puede tener falsos positivos y negativos).
const SALUD = /(diagn[oó]stic|me diagnosticaron|s[ií]ntoma|enfermedad|enferm[oa] de|tratamiento m[eé]dic|medicaci[oó]n|medicamento|me oper|operaci[oó]n quir|internad[oa]|embaraz|depresi[oó]n|ansiedad|psiqui|psic[oó]log|covid|gripe|fiebre|c[aá]ncer|diabetes|\bvih\b|\bhiv\b|lesi[oó]n|fractura)/i;
if (SALUD.test(consulta)) return fin('BLOQUEADA_SALUD', 'POSIBLE_DATO_CLINICO', RESP_SALUD, { legajo });

// Mensaje que recibe WF-03: legajo validado al inicio + consulta, como en el canal de chat.
return fin('VALIDA', '', '', { legajo, mensaje: legajo + ' ' + consulta });

// Normalizar webhook: acepta solo "mensaje" y, opcionalmente, "legajo". Cualquier otro campo del cuerpo
// (id_consulta, origen, estado_aviso, etc.) se ignora: los campos internos los fija el workflow.
const j = $input.first().json || {};
const body = (j.body && typeof j.body === 'object' && !Array.isArray(j.body)) ? j.body : {};
const PERMITIDOS = ['mensaje', 'legajo'];
return [{ json: {
  origen: 'WEBHOOK',
  texto: typeof body.mensaje === 'string' ? body.mensaje : '',
  legajo_declarado: typeof body.legajo === 'string' ? body.legajo : '',
  campos_ignorados: Object.keys(body).filter(k => !PERMITIDOS.includes(k)),
} }];

// Respuesta final: último nodo común a los dos canales.
// El canal se determina por el disparador que se ejecutó, no por datos del usuario.
// Chat: solo el texto para el empleado. Webhook: JSON reducido; lo envía el nodo "Responder al webhook".
const ERROR_TXT = 'En este momento no puedo procesar tu consulta. Por favor, intentá de nuevo más tarde o comunicate con el área correspondiente.';
let canal = 'CHAT';
try { if ($('Consulta por webhook').isExecuted) canal = 'WEBHOOK'; } catch (e) { canal = 'CHAT'; }
let v = {};
try { v = $('Validación previa').first().json || {}; } catch (e) { v = {}; }
const r = $input.first().json || {};
let res;
if (v.resultado === 'VALIDA') {
  // Resultado de WF-03. Si la llamada falló, no hay respuesta válida: texto fijo y estado ERROR.
  const ok = !r.error && typeof r.respuesta === 'string' && r.respuesta && r.id_consulta === v.id_consulta;
  res = ok
    ? { respuesta: r.respuesta, decision: r.decision || '', estado_procesamiento: r.estado_procesamiento || '', registro: r.registro || '', aviso: (r.aviso && r.aviso.estado) || '' }
    : { respuesta: ERROR_TXT, decision: '', estado_procesamiento: 'ERROR', registro: 'DESCONOCIDO', aviso: 'NO_CORRESPONDE' };
} else if (v.resultado === 'BLOQUEADA_SALUD') {
  const reg = (!r.error && r.id_consulta === v.id_consulta) ? 'REGISTRADA' : 'NO_REGISTRADA';
  res = { respuesta: v.respuesta, decision: '', estado_procesamiento: 'BLOQUEADO', registro: reg, aviso: 'NO_CORRESPONDE' };
} else if (v.resultado === 'RECHAZADA') {
  res = { respuesta: v.respuesta || ERROR_TXT, decision: '', estado_procesamiento: 'RECHAZADA', registro: 'NO_REGISTRADA', aviso: 'NO_CORRESPONDE' };
} else {
  // Falla interna de WF-02 (por ejemplo, un error en la normalización o en la validación).
  res = { respuesta: ERROR_TXT, decision: '', estado_procesamiento: 'ERROR', registro: 'NO_REGISTRADA', aviso: 'NO_CORRESPONDE' };
}
if (canal === 'WEBHOOK') {
  return [{ json: { id_consulta: typeof v.id_consulta === 'string' ? v.id_consulta : '', origen: 'WEBHOOK', respuesta: res.respuesta, decision: res.decision,
    estado_procesamiento: res.estado_procesamiento, registro: res.registro, aviso: res.aviso } }];
}
const ref = res.registro === 'REGISTRADA' || res.registro === 'YA_REGISTRADA' ? '\n\nReferencia de tu consulta: ' + v.id_consulta : '';
return [{ json: { output: res.respuesta + ref } }];

// Fila de bloqueo por posible dato clínico (diseño 7.5): la clasificación la asigna esta regla, no el AI Agent.
// No se registra el mensaje: el resumen es un texto fijo.
const v = $input.first().json;
return [{ json: { ...v, fila: {
  id_consulta: v.id_consulta, fecha_hora: v.fecha_hora, origen: v.origen, legajo: v.legajo,
  procedimiento: 'PRO-RH-002', categoria: 'Dato sensible', decision: '', estado_procesamiento: 'BLOQUEADO', codigo_error: '',
  area_destino: 'Salud Ocupacional', urgencia: 'Normal', resumen: '[contenido no registrado]', fuentes: '', id_solicitud: '',
  estado_derivacion: 'Pendiente', estado_aviso: 'NO_APLICA',
} } }];

// Detectar incidente: rama de monitoreo de WF-02. Solo lee resultados ya calculados; no modifica la respuesta.
// Si no hay incidente técnico, no emite nada y WF-04 no se llama. Nunca envía mensajes, legajos ni encabezados.
function codigosIncidente(d) {
  const c = [];
  if (d.resultado_validacion === 'RECHAZADA') return c;
  if (d.resultado_validacion === 'ERROR_INTERNO') return ['ERROR_PROCESAMIENTO'];
  if (d.registro === 'DESCONOCIDO') c.push('INTEGRACION_WF03');
  if (d.codigo_error === 'ERR_SHEETS') c.push('ERR_SHEETS');
  else if (d.estado_procesamiento === 'ERROR' && !c.includes('INTEGRACION_WF03')) c.push('ERROR_PROCESAMIENTO');
  if (d.registro === 'NO_REGISTRADA' && !c.includes('ERR_SHEETS')) c.push('REGISTRO_NO_CONFIRMADO');
  if (d.aviso_estado === 'ERROR_ENVIO') c.push('AVISO_ERROR_ENVIO');
  if (d.aviso_estado === 'VERIFICACION_MANUAL' || d.aviso_verificacion === true) c.push('AVISO_VERIFICACION_MANUAL');
  return c;
}
let canal = 'CHAT';
try { if ($('Consulta por webhook').isExecuted) canal = 'WEBHOOK'; } catch (e) { canal = 'CHAT'; }
let v = {};
try { v = $('Validación previa').first().json || {}; } catch (e) { v = {}; }
const d = {
  workflow_origen: 'WF-02', ejecucion_id: String($execution.id || ''),
  id_consulta: /^CON-[A-Za-z0-9-]{1,60}$/.test(String(v.id_consulta || '')) ? v.id_consulta : '',
  canal, resultado_validacion: '', estado_procesamiento: '', codigo_error: '', registro: '', aviso_estado: '', aviso_verificacion: false,
};
if (v.resultado === 'VALIDA') {
  let r = {};
  try { r = $('Procesar en WF-03').first().json || {}; } catch (e) { r = { error: true }; }
  const ok = !r.error && typeof r.respuesta === 'string' && r.id_consulta === v.id_consulta;
  d.resultado_validacion = 'VALIDA';
  if (!ok) { d.estado_procesamiento = 'ERROR'; d.registro = 'DESCONOCIDO'; }
  else {
    d.estado_procesamiento = String(r.estado_procesamiento || ''); d.codigo_error = String(r.codigo_error || ''); d.registro = String(r.registro || '');
    d.aviso_estado = String((r.aviso && r.aviso.estado) || ''); d.aviso_verificacion = !!(r.aviso && r.aviso.verificacion_manual === true);
  }
} else if (v.resultado === 'BLOQUEADA_SALUD') {
  let b = {};
  try { b = $('Registrar bloqueo').first().json || {}; } catch (e) { b = { error: true }; }
  const reg = !b.error && b.id_consulta === v.id_consulta;
  d.resultado_validacion = 'BLOQUEADA_SALUD'; d.estado_procesamiento = 'BLOQUEADO';
  d.registro = reg ? 'REGISTRADA' : 'NO_REGISTRADA'; d.codigo_error = reg ? '' : 'ERR_SHEETS';
} else if (v.resultado === 'RECHAZADA') {
  d.resultado_validacion = 'RECHAZADA';
} else {
  d.resultado_validacion = 'ERROR_INTERNO'; d.estado_procesamiento = 'ERROR';
}
if (!codigosIncidente(d).length) return [];
return [{ json: d }];
